function inRanges(cp: number, ranges: ReadonlyArray<readonly [number, number]>): boolean {
  let lo = 0
  let hi = ranges.length - 1
  while (lo <= hi) {
    const mid = (lo + hi) >> 1
    const range = ranges[mid]!
    if (cp < range[0]) hi = mid - 1
    else if (cp > range[1]) lo = mid + 1
    else return true
  }
  return false
}

function codePointWidth(cp: number): number {
  if (cp === 0) return 0
  if (cp < 0x20 || (cp >= 0x7f && cp < 0xa0)) return 0 // 제어 문자 — 셀에 오면 폭 없음
  if (inRanges(cp, ZERO_WIDTH)) return 0
  if (inRanges(cp, WIDE)) return 2
  return 1
}

/**
 * 문자열의 터미널 표시 폭. frame-to-ansi 의 셀 symbol(그래핌 하나) 이 주 고객이지만
 * 원본 Bun.stringWidth 처럼 여러 글자 문자열도 합산으로 처리한다.
 *
 *   · ZWJ(U+200D) 로 이어진 뒷부분은 폭을 더하지 않는다 — 👨‍👩‍👧 는 한 셀 뭉치(2)
 *   · VS16(U+FE0F) 은 텍스트 프레젠테이션 기호를 이모지(2)로 승격한다 — ☂️ 등
 *   · 국기(RI 쌍)는 RI 각 1 로 합산 2
 */
export function stringWidth(text: string): number {
  let width = 0
  let joinNext = false
  /** 직전에 폭을 더한 코드포인트의 폭 — VS16 승격이 "1 이었을 때만 +1" 하기 위한 기억. */
  let lastAdded = 0
  for (const ch of text) {
    const cp = ch.codePointAt(0)!
    if (cp === 0x200d) {
      joinNext = true
      continue
    }
    if (cp === 0xfe0f) {
      // VS16: 직전 기호를 이모지 폭(2)으로 승격. 이미 2 였으면 그대로.
      if (lastAdded === 1) {
        width += 1
        lastAdded = 2
      }
      continue
    }
    const w = codePointWidth(cp)
    if (w === 0) continue
    if (joinNext) {
      joinNext = false
      continue
    }
    width += w
    lastAdded = w
  }
  return width
}
